#
# Guidance for Generative AI Marketing Content Generation on AWS
# User-facing deployment script (macOS / Linux / Windows via WSL or Git Bash)
#
# The initial admin credential is generated by AWS Secrets Manager inside the
# stack. You are never asked for a password and none is passed on the command
# line, in an environment variable, or into the CloudFormation template.
#
# Usage:
#   ./scripts/deploy.sh
#   AWS_REGION=us-west-2 ./scripts/deploy.sh
#
# Cleanup:
#   ./scripts/deploy.sh --destroy

set -euo pipefail

# ============================================
# CONFIGURATION
# ============================================
AWS_REGION="${AWS_REGION:-${CDK_DEFAULT_REGION:-us-east-1}}"
STACK_NAME="${STACK_NAME:-ContentGenStack}"
COGNITO_USERNAME="admin"
NODE_MIN_MAJOR=18
REQUIRED_BEDROCK_MODELS=(
  "us.stability.stable-image-style-guide-v1:0"
  "us.amazon.nova-pro-v1:0"
  "amazon.nova-reel-v1:1"
)

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
CDK_DIR="${PROJECT_ROOT}/cdk"

# ============================================
# HELPERS
# ============================================
log()  { echo ""; echo "=== $* ==="; }
info() { echo "    $*"; }
fail() { echo ""; echo "ERROR: $*" >&2; exit 1; }

# ============================================
# PLATFORM DETECTION
# ============================================
detect_platform() {
  case "$(uname -s)" in
    Darwin*)              PLATFORM="macos" ;;
    Linux*)               PLATFORM="linux" ;;
    MINGW*|MSYS*|CYGWIN*) PLATFORM="windows" ;;
    *)                    PLATFORM="unknown" ;;
  esac
  info "Detected platform: ${PLATFORM}"
  if [ "${PLATFORM}" = "unknown" ]; then
    info "Unrecognized platform. The script will continue but is untested here."
  fi
}

# ============================================
# PREREQUISITE CHECKS
# ============================================
check_prerequisites() {
  log "Checking prerequisites"

  command -v aws >/dev/null 2>&1 \
    || fail "AWS CLI v2 is required. Install: https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
  info "AWS CLI: $(aws --version 2>&1)"

  command -v node >/dev/null 2>&1 \
    || fail "Node.js ${NODE_MIN_MAJOR}+ is required. Install: https://nodejs.org/en/download"
  local node_major
  node_major="$(node -v | sed 's/^v//' | cut -d. -f1)"
  if [ "${node_major}" -lt "${NODE_MIN_MAJOR}" ]; then
    fail "Node.js ${NODE_MIN_MAJOR}+ is required (found $(node -v))."
  fi
  info "Node.js: $(node -v)"

  command -v npm >/dev/null 2>&1 || fail "npm is required (ships with Node.js)."
  info "npm: $(npm -v)"

  aws sts get-caller-identity >/dev/null 2>&1 \
    || fail "AWS credentials are not configured or have expired. Run 'aws configure' or set AWS_PROFILE."
}

# ============================================
# CONFIGURATION PROMPTS
# ============================================
prompt_config() {
  log "Collecting configuration"

  if [ -t 0 ] && [ -z "${AWS_REGION_CONFIRMED:-}" ]; then
    read -r -p "    AWS region [${AWS_REGION}]: " input_region || true
    AWS_REGION="${input_region:-${AWS_REGION}}"
  fi
  info "Region: ${AWS_REGION}"
  info "The admin credential is generated in AWS Secrets Manager during deployment."
}

# ============================================
# ENVIRONMENT SETUP
# ============================================
setup_environment() {
  log "Resolving AWS environment"
  ACCOUNT_ID="$(aws sts get-caller-identity --query Account --output text)"
  CALLER_ARN="$(aws sts get-caller-identity --query Arn --output text)"
  info "Account ID: ${ACCOUNT_ID}"
  info "Identity:   ${CALLER_ARN}"
  info "Region:     ${AWS_REGION}"

  export AWS_REGION
  export AWS_DEFAULT_REGION="${AWS_REGION}"
  export CDK_DEFAULT_ACCOUNT="${ACCOUNT_ID}"
  export CDK_DEFAULT_REGION="${AWS_REGION}"
  export STACK_NAME
}

# ============================================
# BEDROCK MODEL ACCESS CHECK
# ============================================
check_bedrock_access() {
  log "Checking Amazon Bedrock model access"
  local available missing=()
  if ! available="$(aws bedrock list-foundation-models --region "${AWS_REGION}" \
        --query 'modelSummaries[].modelId' --output text 2>/dev/null)"; then
    info "Could not list Bedrock foundation models (missing bedrock:ListFoundationModels permission?)."
    info "Skipping the model access check. Verify access manually in the Bedrock console."
    return 0
  fi

  for model in "${REQUIRED_BEDROCK_MODELS[@]}"; do
    local base="${model#us.}"
    if ! echo "${available}" | grep -q "${base%%:*}"; then
      missing+=("${model}")
    fi
  done

  if [ "${#missing[@]}" -gt 0 ]; then
    info "The following models were not found in ${AWS_REGION}:"
    for m in "${missing[@]}"; do info "  - ${m}"; done
    info "Enable them in the Bedrock console: Model access -> Manage model access."
    info "Deployment will continue; generation calls will fail until access is granted."
  else
    info "All required model families are visible in ${AWS_REGION}."
  fi
}

# ============================================
# INSTALL DEPENDENCIES & BUILD FRONTEND
# ============================================
build_frontend() {
  log "Installing frontend dependencies and building the React app"
  cd "${PROJECT_ROOT}"
  npm install
  npm run build
  [ -d "${PROJECT_ROOT}/dist" ] \
    || fail "Frontend build did not produce ./dist. Check the 'npm run build' output above."
  info "Frontend built to ${PROJECT_ROOT}/dist"
}

install_cdk_dependencies() {
  log "Installing CDK dependencies"
  cd "${CDK_DIR}"
  npm install
  info "CDK toolkit: $(npx cdk --version)"
}

# ============================================
# CDK BOOTSTRAP
# ============================================
bootstrap_cdk() {
  log "Checking CDK bootstrap"
  local bootstrap_stack
  bootstrap_stack="$(aws cloudformation describe-stacks --region "${AWS_REGION}" \
    --query "Stacks[?StackName=='CDKToolkit'].StackName" --output text 2>/dev/null || true)"

  if [ -z "${bootstrap_stack}" ] || [ "${bootstrap_stack}" = "None" ]; then
    info "CDKToolkit stack not found. Bootstrapping aws://${ACCOUNT_ID}/${AWS_REGION}"
    cd "${CDK_DIR}"
    npx cdk bootstrap "aws://${ACCOUNT_ID}/${AWS_REGION}"
  else
    info "CDK is already bootstrapped in ${AWS_REGION}."
  fi
}

# ============================================
# DEPLOYMENT
# ============================================
deploy_stack() {
  log "Deploying ${STACK_NAME} to ${AWS_REGION}"
  info "A cold deploy takes roughly 6 minutes (CloudFront is the slowest resource)."
  cd "${CDK_DIR}"
  npx cdk deploy --require-approval never --outputs-file "${PROJECT_ROOT}/cdk-outputs.json"
}

# ============================================
# VALIDATION
# ============================================
stack_output() {
  aws cloudformation describe-stacks --region "${AWS_REGION}" \
    --stack-name "${STACK_NAME}" \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text
}

validate_deployment() {
  log "Validating deployment"

  local status
  status="$(aws cloudformation describe-stacks --region "${AWS_REGION}" \
    --stack-name "${STACK_NAME}" --query 'Stacks[0].StackStatus' --output text)"
  info "Stack status: ${status}"
  case "${status}" in
    CREATE_COMPLETE|UPDATE_COMPLETE) ;;
    *) fail "Stack is in unexpected status '${status}'. Inspect the CloudFormation events in the console." ;;
  esac

  WEBSITE_URL="$(stack_output WebsiteUrl)"
  API_URL="$(stack_output ApiUrl)"
  USER_POOL_ID="$(stack_output UserPoolId)"
  SECRET_NAME="$(stack_output AdminCredentialSecretName)"

  [ -n "${WEBSITE_URL}" ] && [ "${WEBSITE_URL}" != "None" ] \
    || fail "WebsiteUrl output is missing from the stack."
  info "WebsiteUrl:  ${WEBSITE_URL}"
  info "ApiUrl:      ${API_URL}"
  info "UserPoolId:  ${USER_POOL_ID}"
  info "Secret:      ${SECRET_NAME}"

  info "Confirming the admin user exists in Cognito..."
  aws cognito-idp admin-get-user --region "${AWS_REGION}" \
    --user-pool-id "${USER_POOL_ID}" --username "${COGNITO_USERNAME}" \
    --query 'UserStatus' --output text \
    || info "Could not read the admin user. Check the Cognito console."

  info "Confirming the API rejects unauthenticated requests..."
  if command -v curl >/dev/null 2>&1; then
    local unauth
    unauth="$(curl -s -o /dev/null -w '%{http_code}' -X POST \
      -H 'Content-Type: application/json' \
      -d '{"content_type":"email","input":"test"}' \
      "${API_URL}generate-text" || echo "000")"
    info "Unauthenticated POST /generate-text -> HTTP ${unauth}"
    case "${unauth}" in
      401|403) ;;
      *) fail "API did not reject an unauthenticated request (got ${unauth}). Stop and investigate." ;;
    esac
  fi

  info "Checking that the SPA is reachable over HTTPS..."
  if command -v curl >/dev/null 2>&1; then
    local http_code
    http_code="$(curl -s -o /dev/null -w '%{http_code}' "${WEBSITE_URL}" || echo "000")"
    info "HTTP ${http_code} from ${WEBSITE_URL}"
    if [ "${http_code}" != "200" ]; then
      info "CloudFront may still be propagating. Retry in a few minutes."
    fi
  else
    info "curl not found; skipping the HTTP check."
  fi
}

# ============================================
# SUMMARY & CLEANUP INSTRUCTIONS
# ============================================
print_summary() {
  cat <<SUMMARY

============================================================
 Deployment complete
============================================================

  Web UI       : ${WEBSITE_URL}
  API endpoint : ${API_URL}
  Username     : ${COGNITO_USERNAME}

  Retrieve the generated admin credential:

    aws secretsmanager get-secret-value --region ${AWS_REGION} \\
      --secret-id ${SECRET_NAME} --query SecretString --output text

  The credential lives only in AWS Secrets Manager. It is not in the
  CloudFormation template, not in cdk.out/, and not in any log.
  Rotate it after first sign-in and create individual users for your team
  instead of sharing this account.

  Stack outputs were also written to:
    ${PROJECT_ROOT}/cdk-outputs.json

  Next steps:
    1. Open the Web UI and sign in.
    2. Set a Brand Profile so generated copy follows your brand voice.
    3. Add products to the Product Catalog, then try the generators.

  Each signed-in user has their own brand profile, product catalog,
  audiences, regulatory rules and assets. Data is not shared between users.

  To remove every resource created by this Guidance:
    ./scripts/deploy.sh --destroy

  Deleting the stack removes the S3 buckets (autoDeleteObjects is enabled),
  the DynamoDB tables, and the Secrets Manager secret. Export anything you
  want to keep first.

============================================================
SUMMARY
}

# ============================================
# DESTROY
# ============================================
destroy_stack() {
  log "Destroying ${STACK_NAME} in ${AWS_REGION}"
  echo ""
  echo "  WARNING: This permanently deletes the stack, all 6 S3 buckets and"
  echo "  their contents (generated images, videos, brand assets, uploads,"
  echo "  access logs), all 4 DynamoDB tables, the Cognito user pool, and the"
  echo "  Secrets Manager secret holding the admin credential."
  echo ""
  if [ -t 0 ]; then
    read -r -p "  Type 'destroy' to confirm: " confirm
    [ "${confirm}" = "destroy" ] || fail "Aborted. Nothing was deleted."
  else
    fail "Refusing to destroy without an interactive confirmation."
  fi

  cd "${CDK_DIR}"
  npm install
  npx cdk destroy --force
  echo ""
  echo "=== Resources removed ==="
}

# ============================================
# MAIN
# ============================================
main() {
  echo "============================================================"
  echo " Guidance for Generative AI Marketing Content Generation on AWS"
  echo "============================================================"

  detect_platform
  check_prerequisites

  if [ "${1:-}" = "--destroy" ]; then
    setup_environment
    destroy_stack
    exit 0
  fi

  prompt_config
  setup_environment
  check_bedrock_access
  build_frontend
  install_cdk_dependencies
  bootstrap_cdk
  deploy_stack
  validate_deployment
  print_summary
}

main "$@"
